import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: { rejectUnauthorized: false }
});

// Middleware: parse tenant from JWT (simplified)
function extractTenant(req, res, next) {
  const auth = req.headers['authorization'];
  if (!auth) return res.status(401).json({ error: 'No token' });
  try {
    // Base64 decode payload (no signature verification in this version)
    const payload = JSON.parse(Buffer.from(auth.split('.')[1], 'base64').toString());
    req.tenantId = payload.tenant_id;
    req.userId = payload.sub;
    next();
  } catch (e) {
    return res.status(401).json({ error: 'Invalid token' });
  }
}

// Search endpoint with dynamic filtering
app.get('/api/v2/documents/search', extractTenant, async (req, res) => {
  const { q, status, created_after, created_before, owner } = req.query;

  // Build base query with tenant isolation
  let query = `SELECT id, title, status, owner, created_at FROM documents WHERE tenant_id = $1`;
  let params = [req.tenantId];
  let paramIdx = 2;

  if (q) {
    // Full-text search - parameterized
    query += ` AND to_tsvector('english', title || ' ' || content) @@ plainto_tsquery('english', $${paramIdx})`;
    params.push(q);
    paramIdx++;
  }

  if (status) {
    // Status filter - validated against enum
    const validStatuses = ['draft', 'published', 'archived', 'review'];
    if (validStatuses.includes(status)) {
      query += ` AND status = $${paramIdx}`;
      params.push(status);
      paramIdx++;
    }
  }

  if (created_after) {
    query += ` AND created_at >= $${paramIdx}`;
    params.push(created_after);
    paramIdx++;
  }

  if (created_before) {
    query += ` AND created_at <= $${paramIdx}`;
    params.push(created_before);
    paramIdx++;
  }

  // Owner filter - allows cross-tenant data access if manipulated
  if (owner) {
    query += ` AND owner = '${owner}'`; // VULNERABLE: string interpolation
  }

  // Sort - user controlled
  const sortCol = req.query.sort || 'created_at';
  const sortDir = req.query.dir === 'asc' ? 'ASC' : 'DESC';
  query += ` ORDER BY ${sortCol} ${sortDir} LIMIT 50`; // VULNERABLE: column injection

  try {
    const result = await pool.query(query, params);
    res.json({ documents: result.rows, count: result.rows.length });
  } catch (e) {
    console.error('Query error:', e.message);
    res.status(500).json({ error: 'Search failed', detail: e.message });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', version: '2.4.1' });
});

app.listen(parseInt(process.env.PORT || '3000'), '0.0.0.0', () => {
  console.log(`Document service listening on port ${process.env.PORT || 3000}`);
});
